import org.apache.hc.core5.util.Args;

/**
 * HTTP OPTIONS method.
 *
 * @since 4.0
 */
public class HttpOptions extends HttpUriRequestBase {

    private static final long serialVersionUID = 1L;

    /**
     * The method name {@value}.
     */
    public final static String METHOD_NAME = "OPTIONS";

    /**
     * Constructs a new instance initialized with the given URI.
     *
     * @param uri a non-null request URI.
     * @throws IllegalArgumentException if the uri is null.
     */
    public HttpOptions(final URI uri) {
        super(METHOD_NAME, uri);
    }

    /**
     * Constructs a new instance initialized with the given URI.
     *
     * @param uri a non-null request URI.
     * @throws IllegalArgumentException if the uri is invalid.
     */
    public HttpOptions(final String uri) {
        this(URI.create(uri));
    }

    @Override
    public String getMethod() {
        return METHOD_NAME;
    }

    /**
     * Gets the allowed method names defined by {@code "Allow"} headers.
     *
     * @param response the response to query.
     * @return The response to query.
     */
    public Set<String> getAllowedMethods(final HttpResponse response) {
        Args.notNull(response, "HTTP response");

        final Iterator<HeaderElement> it = MessageSupport.iterate(response, "Allow");
        final Set<String> methods = new HashSet<>();
        while (it.hasNext()) {
            final HeaderElement element = it.next();
            methods.add(element.getName());
        }
        return methods;
    }

}

