  @ConfigurationEntry(type = "Comma-separated list of strings", description = {"Keys by which to prioritize transport order candidates for assignment.", "Possible keys:", "BY_AGE: Sort by transport order age, oldest first.", "BY_DEADLINE: Sort by transport order deadline, most urgent first.", "DEADLINE_AT_RISK_FIRST: Sort orders with deadlines at risk first.", "BY_COMPLETE_ROUTING_COSTS: Sort by complete routing costs, lowest first.", "BY_INITIAL_ROUTING_COSTS: Sort by routing costs for the first destination.", "BY_ORDER_NAME: Sort by transport order name, lexicographically.", "BY_ORDER_TYPE_PRIORITY: Sort by priority of the order type configured for the vehicles, highest (i.e. lowest integer value) first."}, changesApplied = ConfigurationEntry.ChangesApplied.ON_APPLICATION_START, orderKey = "0_assign") List<String> orderCandidatePriorities();
