  @ConfigurationEntry(type = "Integer", description = "The time (in ms) to wait before creating recharge orders for idle vehicles.", changesApplied = ConfigurationEntry.ChangesApplied.INSTANTLY, orderKey = "3_recharge_1") long rechargeIdleVehiclesDelay();
