import static java.util.Objects.requireNonNull;

public class IsParkable implements ParkVehicleSelectionFilter {
  private final TCSObjectService objectService;
  private final DefaultDispatcherConfiguration configuration;
  private final TimeProvider timeProvider;

  @Inject public IsParkable(TCSObjectService objectService, DefaultDispatcherConfiguration configuration, TimeProvider timeProvider) {
    this.objectService = requireNonNull(objectService, "objectService");
    this.configuration = requireNonNull(configuration, "configuration");
    this.timeProvider = requireNonNull(timeProvider, "timeProvider");
  }

  @Override public Collection<String> apply(Vehicle vehicle) {
    return parkable(vehicle) ? new ArrayList<>() : Arrays.asList(getClass().getName());
  }

  private boolean parkable(Vehicle vehicle) {
    return vehicle.getIntegrationLevel() == Vehicle.IntegrationLevel.TO_BE_UTILIZED
        && inProcStateIdleFor(vehicle, configuration.parkIdleVehiclesDelay())
        && vehicle.hasState(Vehicle.State.IDLE)
        && vehicle.getCurrentPosition() != null
        && !isParkingPosition(vehicle.getCurrentPosition())
        && vehicle.getOrderSequence() == null
        && hasAcceptableOrderTypesForParking(vehicle);
  }

  private boolean inProcStateIdleFor(Vehicle vehicle, long millis) {
    return vehicle.hasProcState(Vehicle.ProcState.IDLE)
        && vehicle.getProcStateTimestamp().plusMillis(millis).isBefore(timeProvider.getCurrentTimeInstant());
  }

  private boolean isParkingPosition(TCSObjectReference<Point> positionRef) {
    return positionRef != null && objectService.fetch(Point.class, positionRef).orElseThrow().isParkingPosition();
  }

  private boolean hasAcceptableOrderTypesForParking(Vehicle vehicle) {
    return vehicle.getAcceptableOrderTypes().stream().anyMatch(type -> type.getName().equals(OrderConstants.TYPE_PARK) || type.getName().equals(OrderConstants.TYPE_ANY));
  }
}

