    return orientationAngle;
  }

  public VehicleStatusMessage setOrientationAngle(double orientationAngle) {
    this.orientationAngle = orientationAngle;
    return this;
  }

  public boolean isPaused() {
    return paused;
  }

  public VehicleStatusMessage setPaused(boolean paused) {
    this.paused = paused;
    return this;
  }

  public VehicleTO.State getState() {
    return state;
  }

  public VehicleStatusMessage setState(VehicleTO.State state) {
    this.state = state;
    return this;
  }

